package com.vocal.service;
import com.vocal.dto.CommerceDtos.*; import com.vocal.entity.*; import com.vocal.exception.ApiException; import com.vocal.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.security.Principal; import java.util.*;
@Service @RequiredArgsConstructor public class CartService { private final UserRepository users; private final ProductVariantRepository variants; private final CartItemRepository carts; private User user(Principal p){return users.findByEmail(p.getName()).orElseThrow();} @Transactional public List<CartLine> add(AddCartRequest r, Principal p){User u=user(p); ProductVariant v=variants.findById(r.variantId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Variant not found")); if(v.getStock()<r.quantity()) throw new ApiException(HttpStatus.BAD_REQUEST,"Insufficient stock"); CartItem item=carts.findByUserIdAndVariantId(u.getId(),v.getId()).orElse(CartItem.builder().user(u).variant(v).quantity(0).build()); item.setQuantity(item.getQuantity()+r.quantity()); carts.save(item); return list(p);} public List<CartLine> list(Principal p){return carts.findByUserId(user(p).getId()).stream().map(this::line).toList();} @Transactional public void remove(Long id, Principal p){carts.deleteById(id);} private CartLine line(CartItem c){ProductVariant v=c.getVariant(); Product pr=v.getProduct(); BigDecimal price=v.getPriceOverride()!=null?v.getPriceOverride():pr.getPrice(); String image=pr.getImageUrls().isEmpty()?null:pr.getImageUrls().get(0); return new CartLine(c.getId(),v.getId(),pr.getName(),v.getSize(),v.getColor(),c.getQuantity(),price,image);} }
